t.script:

// Global GuardMap object
window.guardMap = {
    map: null,
    markers: {},
    infoWindows: {},
    autoRefreshInterval: null,
    pathPolyline: null,
    pathMarkers: [],
    geofences: [],
    geofencesVisible: true,
    markerClusterer: null,
    clusteringEnabled: true,
    heatmapLayer: null,
    heatmapEnabled: false,

    init: function() {
        console.log('Initializing GuardMap...');
        this.initMap();
        this.loadGuardLocations();
        this.loadGeofences();
        this.setupAutoRefresh();
    },

    initMap: function() {
        console.log('Initializing Google Map...');
        // Default center (Dubai, UAE)
        const defaultCenter = { lat: 25.2048, lng: 55.2708 };

        // Detect if mobile device
        const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);

        this.map = new google.maps.Map(document.getElementById('map'), {
            zoom: 12,
            center: defaultCenter,
            mapTypeId: 'roadmap',
            mapTypeControl: false,
            streetViewControl: false,
            fullscreenControl: true,
            zoomControl: false, // We use custom zoom controls
            gestureHandling: isMobile ? 'greedy' : 'auto',
            disableDefaultUI: false,
            minZoom: 3,
            maxZoom: 20,
            styles: [
                {
                    featureType: "poi",
                    elementType: "labels",
                    stylers: [{ visibility: "off" }]
                }
            ]
        });

        // Hide loading overlay
        const loadingEl = document.getElementById('loading');
        if (loadingEl) {
            loadingEl.classList.remove('active');
        }
        console.log('Map initialized successfully');
    },

    // Zoom control methods
    zoomIn: function() {
        const currentZoom = this.map.getZoom();
        this.map.setZoom(currentZoom + 1);
    },

    zoomOut: function() {
        const currentZoom = this.map.getZoom();
        this.map.setZoom(currentZoom - 1);
    },

    fitAllMarkers: function() {
        const markers = Object.values(this.markers);
        if (markers.length === 0) {
            alert('No guards to display');
            return;
        }

        const bounds = new google.maps.LatLngBounds();
        markers.forEach(marker => {
            bounds.extend(marker.getPosition());
        });

        this.map.fitBounds(bounds);

        // Prevent over-zooming for single marker
        if (markers.length === 1) {
            setTimeout(() => {
                this.map.setZoom(15);
            }, 100);
        }
    },

    // Map type switcher
    setMapType: function(mapType) {
        this.map.setMapTypeId(mapType);

        // Update button states
        document.querySelectorAll('.map-type-btn').forEach(btn => {
            btn.classList.remove('active');
        });
        document.querySelector(`[data-type="${mapType}"]`).classList.add('active');
    },

    loadGuardLocations: function() {
        console.log('Loading guard locations...');

        // Show loading state
        const countContainer = document.getElementById('guard-count');
        if (countContainer) {
            countContainer.textContent = 'Loading...';
        }

        // Use Odoo's rpc mechanism for proper authentication
        if (typeof odoo !== 'undefined' && odoo.rpc) {
            // Use Odoo's rpc if available
            odoo.rpc('/guardpro/guards/locations', {})
                .then(response => {
                    console.log('Guard locations response:', response);
                    // odoo.rpc() automatically unwraps JSON-RPC response
                    // but sometimes it returns the full envelope, handle both cases
                    const result = response.result || response;
                    console.log('Extracted result:', result);
                    if (result.success) {
                        this.updateMarkers(result.locations);
                        this.updateGuardsList(result.locations);
                    } else {
                        console.error('Error loading locations:', result.error);
                        this.updateGuardsList([]);
                    }
                })
                .catch(error => {
                    console.error('Error fetching guard locations:', error);
                    this.updateGuardsList([]);
                });
        } else {
            // Fallback to direct fetch with CSRF token
            const csrfToken = document.querySelector('meta[name=csrf-token]')?.getAttribute('content') || 
                            document.querySelector('input[name=csrf_token]')?.value;

            fetch('/guardpro/guards/locations', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-Requested-With': 'XMLHttpRequest',
                    'X-CSRFToken': csrfToken
                },
                credentials: 'same-origin',
                body: JSON.stringify({
                    jsonrpc: "2.0",
                    method: "call",
                    params: {},
                    id: null
                })
            })
            .then(response => response.json())
            .then(response => {
                console.log('Guard locations response (fetch):', response);
                // Handle JSON-RPC response structure
                const result = response.result || response;
                console.log('Extracted result (fetch):', result);
                if (result.success) {
                    this.updateMarkers(result.locations);
                    this.updateGuardsList(result.locations);
                } else {
                    console.error('Error loading locations:', result.error);
                    this.updateGuardsList([]);
                }
            })
            .catch(error => {
                console.error('Error fetching guard locations:', error);
                this.updateGuardsList([]);
            });
        }
    },

    updateMarkers: function(locations) {
        console.log('Updating markers for', locations.length, 'guards');

        // Clear existing markers
        if (this.markerClusterer) {
            this.markerClusterer.clearMarkers();
        }
        Object.values(this.markers).forEach(marker => marker.setMap(null));
        Object.values(this.infoWindows).forEach(infoWindow => infoWindow.close());
        this.markers = {};
        this.infoWindows = {};

        if (!locations || locations.length === 0) {
            console.log('No locations to display');
            return;
        }

        const bounds = new google.maps.LatLngBounds();
        const markersArray = [];

        locations.forEach((guard) => {
            const position = {
                lat: parseFloat(guard.latitude),
                lng: parseFloat(guard.longitude)
            };

            // Determine marker color based on last update time
            let markerColor = '#10b981'; // green - active (< 5 min)
            if (guard.time_since_update > 30) {
                markerColor = '#ef4444'; // red - inactive (> 30 min)
            } else if (guard.time_since_update > 5) {
                markerColor = '#f59e0b'; // yellow - stale (5-30 min)
            }

            // Create custom marker icon
            const markerIcon = {
                path: google.maps.SymbolPath.CIRCLE,
                scale: 10,
                fillColor: markerColor,
                fillOpacity: 0.9,
                strokeColor: '#ffffff',
                strokeWeight: 2
            };

            const marker = new google.maps.Marker({
                position: position,
                map: this.clusteringEnabled ? null : this.map,
                icon: markerIcon,
                title: guard.name,
                animation: google.maps.Animation.DROP
            });

            // Create info window
            const lastUpdateText = guard.time_since_update 
                ? `${guard.time_since_update} min ago` 
                : 'Just now';

            const infoContent = `
                <div style="padding: 10px; min-width: 200px;">
                    <h3 style="margin: 0 0 10px 0;">${guard.name}</h3>
                    <p style="margin: 5px 0;"><strong>Badge:</strong> ${guard.badge_number}</p>
                    <p style="margin: 5px 0;"><strong>Site:</strong> ${guard.current_site}</p>
                    <p style="margin: 5px 0;"><strong>Phone:</strong> ${guard.phone || 'N/A'}</p>
                    <p style="margin: 5px 0;"><strong>Last Update:</strong> ${lastUpdateText}</p>
                    <p style="margin: 10px 0 0 0;">
                        <a href="/web#id=${guard.id}&model=guard.profile&view_type=form" 
                           target="_blank" class="btn btn-primary btn-sm">
                           View Profile
                        </a>
                    </p>
                </div>
            `;

            const infoWindow = new google.maps.InfoWindow({
                content: infoContent
            });

            marker.addListener('click', () => {
                // Close all other info windows
                Object.values(this.infoWindows).forEach(iw => iw.close());
                infoWindow.open(this.map, marker);
            });

            this.markers[guard.id] = marker;
            this.infoWindows[guard.id] = infoWindow;
            markersArray.push(marker);

            bounds.extend(position);
        });

        // Setup clustering if enabled
        if (this.clusteringEnabled && typeof markerClusterer !== 'undefined') {
            this.markerClusterer = new markerClusterer.MarkerClusterer({
                map: this.map,
                markers: markersArray,
                algorithm: new markerClusterer.GridAlgorithm({
                    gridSize: 60,
                    maxDistance: 40000
                })
            });
            console.log('Marker clustering enabled with', markersArray.length, 'markers');
        } else {
            // Display markers directly without clustering
            markersArray.forEach(m => m.setMap(this.map));
        }

        // Fit map to show all markers
        if (locations.length > 0) {
            this.map.fitBounds(bounds);

            // Prevent over-zooming for single marker
            if (locations.length === 1) {
                this.map.setZoom(15);
            }
        }
    },

    updateGuardsList: function(locations) {
        const listContainer = document.getElementById('guards-list');
        const countContainer = document.getElementById('guard-count');

        if (countContainer) {
            countContainer.textContent = `${locations.length} guard${locations.length !== 1 ? 's' : ''} active`;
        }

        if (!listContainer) return;

        if (!locations || locations.length === 0) {
            listContainer.innerHTML = '<p style="color: #999; font-size: 12px;">No active guards with location data</p>';
            return;
        }

        let html = '';
        locations.forEach((guard) => {
            let statusClass = 'status-active';
            if (guard.time_since_update > 30) {
                statusClass = 'status-inactive';
            } else if (guard.time_since_update > 5) {
                statusClass = 'status-stale';
            }

            const lastUpdateText = guard.time_since_update 
                ? `${guard.time_since_update} min ago` 
                : 'Just now';

            html += `
                <div class="guard-info" onclick="guardMap.focusGuard(${guard.id})" style="cursor: pointer;">
                    <div>
                        <span class="status-indicator ${statusClass}"></span>
                        <span class="guard-name">${guard.name}</span>
                    </div>
                    <div class="guard-badge">Badge: ${guard.badge_number}</div>
                    <div class="guard-time">${lastUpdateText}</div>
                </div>
            `;
        });

        listContainer.innerHTML = html;
    },

    focusGuard: function(guardId) {
        const marker = this.markers[guardId];
        const infoWindow = this.infoWindows[guardId];

        if (marker && infoWindow) {
            this.map.panTo(marker.getPosition());
            this.map.setZoom(16);

            // Close all other info windows
            Object.values(this.infoWindows).forEach(iw => iw.close());
            infoWindow.open(this.map, marker);
        }
    },

    refreshLocations: function() {
        console.log('Refreshing locations...');
        this.loadGuardLocations();
    },

    setupAutoRefresh: function() {
        const checkbox = document.getElementById('auto-refresh');

        if (!checkbox) return;

        const startAutoRefresh = () => {
            if (this.autoRefreshInterval) {
                clearInterval(this.autoRefreshInterval);
            }
            this.autoRefreshInterval = setInterval(() => {
                this.loadGuardLocations();
            }, 30000); // 30 seconds
        };

        checkbox.addEventListener('change', (e) => {
            if (e.target.checked) {
                startAutoRefresh();
            } else {
                if (this.autoRefreshInterval) {
                    clearInterval(this.autoRefreshInterval);
                    this.autoRefreshInterval = null;
                }
            }
        });

        // Start auto-refresh if checkbox is checked
        if (checkbox.checked) {
            startAutoRefresh();
        }
    },

    showGuardPath: function() {
        const guardId = document.getElementById('path-guard-select').value;
        const timeRange = document.getElementById('path-time-range').value;

        if (!guardId) {
            alert('Please select a guard first');
            return;
        }

        // Clear existing path
        this.clearPath();

        // Calculate start datetime
        const endDate = new Date();
        const startDate = new Date(endDate.getTime() - (timeRange * 60 * 60 * 1000));

        const pathParams = {
            guard_id: guardId,
            start_datetime: startDate.toISOString(),
            end_datetime: endDate.toISOString()
        };

        // Fetch path data
        if (typeof odoo !== 'undefined' && odoo.rpc) {
            odoo.rpc('/guardpro/guard/path', pathParams)
            .then(response => {
                const result = response.result || response;
                if (result.success && result.path && result.path.length > 0) {
                    this.displayPath(result.path, result.guard);
                } else {
                    alert('No location history found for this guard in the selected time range');
                }
            })
            .catch(error => {
                console.error('Error fetching guard path:', error);
                alert('Error loading path data: ' + error);
            });
        } else {
            // Fallback to direct fetch with CSRF token
            const csrfToken = document.querySelector('meta[name=csrf-token]')?.getAttribute('content') || 
                            document.querySelector('input[name=csrf_token]')?.value;

            fetch('/guardpro/guard/path', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-Requested-With': 'XMLHttpRequest',
                    'X-CSRFToken': csrfToken
                },
                credentials: 'same-origin',
                body: JSON.stringify({
                    jsonrpc: "2.0",
                    method: "call",
                    params: pathParams,
                    id: null
                })
            })
            .then(response => response.json())
            .then(response => {
                console.log('Guard path response (fetch):', response);
                const result = response.result || response;
                if (result.success && result.path && result.path.length > 0) {
                    this.displayPath(result.path, result.guard);
                } else {
                    alert('No location history found for this guard in the selected time range');
                }
            })
            .catch(error => {
                console.error('Error fetching guard path:', error);
                alert('Error loading path data: ' + error);
            });
        }
    },

    displayPath: function(pathData, guardInfo) {
        if (!pathData || pathData.length === 0) return;

        // Create path coordinates array
        const pathCoordinates = pathData.map(point => ({
            lat: parseFloat(point.latitude),
            lng: parseFloat(point.longitude)
        }));

        // Create polyline
        this.pathPolyline = new google.maps.Polyline({
            path: pathCoordinates,
            geodesic: true,
            strokeColor: '#3b82f6',
            strokeOpacity: 0.8,
            strokeWeight: 3,
            map: this.map
        });

        // Add start marker (green)
        const startMarker = new google.maps.Marker({
            position: pathCoordinates[0],
            map: this.map,
            icon: {
                path: google.maps.SymbolPath.CIRCLE,
                scale: 8,
                fillColor: '#10b981',
                fillOpacity: 1,
                strokeColor: '#ffffff',
                strokeWeight: 2
            },
            title: 'Start: ' + pathData[0].timestamp
        });

        // Add end marker (red)
        const endMarker = new google.maps.Marker({
            position: pathCoordinates[pathCoordinates.length - 1],
            map: this.map,
            icon: {
                path: google.maps.SymbolPath.CIRCLE,
                scale: 8,
                fillColor: '#ef4444',
                fillOpacity: 1,
                strokeColor: '#ffffff',
                strokeWeight: 2
            },
            title: 'End: ' + pathData[pathData.length - 1].timestamp
        });

        this.pathMarkers.push(startMarker, endMarker);

        // Add info windows
        const startInfo = new google.maps.InfoWindow({
            content: `<div style="padding: 10px;">
                <strong>Start Point</strong><br/>
                Guard: ${guardInfo.name}<br/>
                Time: ${new Date(pathData[0].timestamp).toLocaleString()}
            </div>`
        });

        const endInfo = new google.maps.InfoWindow({
            content: `<div style="padding: 10px;">
                <strong>End Point</strong><br/>
                Guard: ${guardInfo.name}<br/>
                Time: ${new Date(pathData[pathData.length - 1].timestamp).toLocaleString()}
            </div>`
        });

        startMarker.addListener('click', () => {
            startInfo.open(this.map, startMarker);
        });

        endMarker.addListener('click', () => {
            endInfo.open(this.map, endMarker);
        });

        // Fit bounds to show entire path
        const bounds = new google.maps.LatLngBounds();
        pathCoordinates.forEach(coord => bounds.extend(coord));
        this.map.fitBounds(bounds);

        console.log(`Displayed path with ${pathData.length} points for guard ${guardInfo.name}`);
    },

    clearPath: function() {
        // Remove polyline
        if (this.pathPolyline) {
            this.pathPolyline.setMap(null);
            this.pathPolyline = null;
        }

        // Remove path markers
        this.pathMarkers.forEach(marker => marker.setMap(null));
        this.pathMarkers = [];

        console.log('Path cleared');
    },

    loadGeofences: function() {
        console.log('Loading site geofences...');

        if (typeof odoo !== 'undefined' && odoo.rpc) {
            odoo.rpc('/guardpro/sites/geofences', {})
                .then(response => {
                    const result = response.result || response;
                    if (result.success && result.geofences) {
                        this.displayGeofences(result.geofences);
                    }
                })
                .catch(error => {
                    console.error('Error fetching geofences:', error);
                });
        } else {
            // Fallback to direct fetch with CSRF token
            const csrfToken = document.querySelector('meta[name=csrf-token]')?.getAttribute('content') || 
                            document.querySelector('input[name=csrf_token]')?.value;

            fetch('/guardpro/sites/geofences', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-Requested-With': 'XMLHttpRequest',
                    'X-CSRFToken': csrfToken
                },
                credentials: 'same-origin',
                body: JSON.stringify({
                    jsonrpc: "2.0",
                    method: "call",
                    params: {},
                    id: null
                })
            })
            .then(response => response.json())
            .then(response => {
                console.log('Geofences response (fetch):', response);
                const result = response.result || response;
                if (result.success && result.geofences) {
                    this.displayGeofences(result.geofences);
                }
            })
            .catch(error => {
                console.error('Error fetching geofences:', error);
            });
        }
    },

    displayGeofences: function(geofenceData) {
        console.log('Displaying', geofenceData.length, 'geofences');

        geofenceData.forEach(geofence => {
            let shape;

            if (geofence.type === 'circle') {
                // Create circle
                shape = new google.maps.Circle({
                    center: geofence.center,
                    radius: geofence.radius,
                    strokeColor: '#8b5cf6',
                    strokeOpacity: 0.8,
                    strokeWeight: 2,
                    fillColor: '#8b5cf6',
                    fillOpacity: 0.15,
                    map: this.map,
                    clickable: true
                });
            } else if (geofence.type === 'polygon' && geofence.polygon) {
                // Create polygon
                const coords = geofence.polygon.map(point => ({
                    lat: parseFloat(point.lat || point.latitude),
                    lng: parseFloat(point.lng || point.longitude)
                }));

                shape = new google.maps.Polygon({
                    paths: coords,
                    strokeColor: '#8b5cf6',
                    strokeOpacity: 0.8,
                    strokeWeight: 2,
                    fillColor: '#8b5cf6',
                    fillOpacity: 0.15,
                    map: this.map,
                    clickable: true
                });
            }

            if (shape) {
                // Add info window
                const infoWindow = new google.maps.InfoWindow({
                    content: `<div style="padding: 10px;">
                        <h4 style="margin: 0 0 8px 0;">${geofence.name}</h4>
                        <p style="margin: 3px 0;"><strong>Code:</strong> ${geofence.code}</p>
                        <p style="margin: 3px 0;"><strong>Client:</strong> ${geofence.client}</p>
                        <p style="margin: 3px 0;"><strong>Type:</strong> ${geofence.type}</p>
                        ${geofence.type === 'circle' ? 
                            `<p style="margin: 3px 0;"><strong>Radius:</strong> ${geofence.radius}m</p>` : ''}
                    </div>`
                });

                // Add click listener
                google.maps.event.addListener(shape, 'click', (event) => {
                    infoWindow.setPosition(event.latLng || geofence.center);
                    infoWindow.open(this.map);
                });

                this.geofences.push({
                    shape: shape,
                    infoWindow: infoWindow,
                    data: geofence
                });
            }
        });

        console.log('Geofences displayed:', this.geofences.length);
    },

    toggleGeofences: function() {
        this.geofencesVisible = !this.geofencesVisible;

        this.geofences.forEach(item => {
            item.shape.setMap(this.geofencesVisible ? this.map : null);
            if (!this.geofencesVisible && item.infoWindow) {
                item.infoWindow.close();
            }
        });

        console.log('Geofences', this.geofencesVisible ? 'shown' : 'hidden');
    },

    toggleClustering: function() {
        this.clusteringEnabled = !this.clusteringEnabled;

        // Reload markers with new clustering setting
        this.loadGuardLocations();

        console.log('Marker clustering', this.clusteringEnabled ? 'enabled' : 'disabled');
    },

    toggleHeatmap: function() {
        this.heatmapEnabled = !this.heatmapEnabled;

        if (this.heatmapEnabled) {
            const dataSource = document.getElementById('heatmap-data-source').value;
            this.loadHeatmapData(dataSource);
        } else {
            this.hideHeatmap();
        }

        console.log('Heatmap', this.heatmapEnabled ? 'enabled' : 'disabled');
    },

    loadHeatmapData: function(dataSource) {
        console.log('Loading heatmap data from:', dataSource);

        if (dataSource === 'current') {
            // Use current guard locations
            const heatmapData = [];
            Object.values(this.markers).forEach(marker => {
                heatmapData.push(new google.maps.LatLng(
                    marker.getPosition().lat(),
                    marker.getPosition().lng()
                ));
            });
            this.displayHeatmap(heatmapData);
        } else {
            // Load location history for heatmap
            // Get all guard IDs
            const guardIds = Object.keys(this.markers).map(id => parseInt(id));

            const heatmapParams = {
                guard_ids: guardIds,
                start_datetime: new Date(Date.now() - 24*60*60*1000).toISOString(),
                end_datetime: new Date().toISOString()
            };

            if (typeof odoo !== 'undefined' && odoo.rpc) {
                odoo.rpc('/guardpro/guards/paths/multiple', heatmapParams)
                .then(response => {
                    const result = response.result || response;
                    if (result.success && result.paths) {
                        const heatmapData = [];
                        Object.values(result.paths).forEach(guardPath => {
                            guardPath.path.forEach(point => {
                                heatmapData.push(new google.maps.LatLng(
                                    parseFloat(point.latitude),
                                    parseFloat(point.longitude)
                                ));
                            });
                        });
                        this.displayHeatmap(heatmapData);
                    }
                })
                .catch(error => {
                    console.error('Error loading heatmap data:', error);
                    alert('Error loading heatmap data');
                });
            } else {
                // Fallback to direct fetch with CSRF token
                const csrfToken = document.querySelector('meta[name=csrf-token]')?.getAttribute('content') || 
                                document.querySelector('input[name=csrf_token]')?.value;

                fetch('/guardpro/guards/paths/multiple', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'X-Requested-With': 'XMLHttpRequest',
                        'X-CSRFToken': csrfToken
                    },
                    credentials: 'same-origin',
                    body: JSON.stringify({
                        jsonrpc: "2.0",
                        method: "call",
                        params: heatmapParams,
                        id: null
                    })
                })
                .then(response => response.json())
                .then(response => {
                    console.log('Heatmap paths response (fetch):', response);
                    const result = response.result || response;
                    if (result.success && result.paths) {
                        const heatmapData = [];
                        Object.values(result.paths).forEach(guardPath => {
                            guardPath.path.forEach(point => {
                                heatmapData.push(new google.maps.LatLng(
                                    parseFloat(point.latitude),
                                    parseFloat(point.longitude)
                                ));
                            });
                        });
                        this.displayHeatmap(heatmapData);
                    }
                })
                .catch(error => {
                    console.error('Error loading heatmap data:', error);
                    alert('Error loading heatmap data');
                });
            }
        }
    },

    displayHeatmap: function(heatmapData) {
        if (!heatmapData || heatmapData.length === 0) {
            alert('No data available for heatmap');
            return;
        }

        // Remove existing heatmap
        if (this.heatmapLayer) {
            this.heatmapLayer.setMap(null);
        }

        // Create heatmap layer
        this.heatmapLayer = new google.maps.visualization.HeatmapLayer({
            data: heatmapData,
            map: this.map,
            radius: 50,
            opacity: 0.6,
            gradient: [
                'rgba(0, 255, 255, 0)',
                'rgba(0, 255, 255, 1)',
                'rgba(0, 191, 255, 1)',
                'rgba(0, 127, 255, 1)',
                'rgba(0, 63, 255, 1)',
                'rgba(0, 0, 255, 1)',
                'rgba(0, 0, 223, 1)',
                'rgba(0, 0, 191, 1)',
                'rgba(0, 0, 159, 1)',
                'rgba(0, 0, 127, 1)',
                'rgba(63, 0, 91, 1)',
                'rgba(127, 0, 63, 1)',
                'rgba(191, 0, 31, 1)',
                'rgba(255, 0, 0, 1)'
            ]
        });

        // Hide regular markers when heatmap is shown
        Object.values(this.markers).forEach(marker => marker.setVisible(false));
        if (this.markerClusterer) {
            this.markerClusterer.clearMarkers();
        }

        console.log('Heatmap displayed with', heatmapData.length, 'data points');
    },

    hideHeatmap: function() {
        if (this.heatmapLayer) {
            this.heatmapLayer.setMap(null);
            this.heatmapLayer = null;
        }

        // Show regular markers again
        Object.values(this.markers).forEach(marker => marker.setVisible(true));
        this.loadGuardLocations(); // Reload to reinitialize clustering if needed

        console.log('Heatmap hidden');
    }
};

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', function() {
    console.log('DOM loaded, initializing GuardMap...');
    // Wait a bit for Google Maps to load
    setTimeout(() => {
        if (typeof google !== 'undefined' && google.maps) {
            guardMap.init();
        } else {
            console.error('Google Maps not loaded');
        }
    }, 1000);
});
